# ENGR 391 (Numerical Methods, Dr. Wuthrich, Fall 2026) — theory bank. Final covers Lessons 1–4 and 6–8 (not Lesson 5, ML).
# The exam is open book (lecture slides, own notes, Octave/MATLAB allowed), so instead of formula-sheet tags each result points to the
# lesson where it lives: "(Lesson N)". The real exam's theory part is MCQ/T-F (see the midterm practice sheet), so the "Exam-style
# theory" topic mirrors that format with original questions.
C = "engr391"
L = lambda n, t: f"Lesson {n} – {t}"
LS = lambda n: f"(Lesson {n})"
DEF = "(definition, not on the sheet)"
Q = []
def add(kind, id, topic, q, exp, src, **kw):
    d = dict(id=f"e391-{id}", course=C, topic=topic, type=kind, question=q, explanation=exp, source=src); d.update(kw); Q.append(d)
def mcq(id, topic, q, choices, ans, exp, src): add("mcq", id, topic, q, exp, src, choices=choices, answer=ans)
def tf(id, topic, q, ans, exp, src): add("tf", id, topic, q, exp, src, answer=ans)
def sa(id, topic, q, ans, exp, src, kw=()): add("short", id, topic, q, exp, src, answer=ans, keywords=list(kw))

T = "Exam-style theory"; s = "Midterm practice sheet format"
tf("ex-01", T, "When $Ax=b$ is solved with a correctly applied $PA=LU$ decomposition, the backward error $\\|b-Ax_c\\|$ is exactly zero.", False, "LU has no truncation error, but floating-point round-off still leaves a small nonzero residual " + LS(3) + ".", s)
tf("ex-02", T, "Bisection can locate the root $r=1$ of $f(x)=(x-1)^2$.", False, "$f\\ge0$ everywhere, so there's no interval with $f(a)f(b)<0$ " + LS(2) + ".\nA double root doesn't change sign, so bracketing methods can't see it.", s)
mcq("ex-03", T, "$f$ is continuous with $f(a)<0$ and $f(b)>0$. Then:", ["There is at least one root in $[a,b]$", "There is exactly one root", "There is no root", "Not enough information"], 0, "Intermediate value theorem " + LS(2) + ".\nThere could be 3, 5, … roots. Exactly one would need monotonic $f$.", s)
mcq("ex-04", T, "For an approximation $x_c$ of a simple root, an estimate of the RELATIVE error is:", ["$\\left|\\dfrac{f(x_c)}{x_c\\,f'(x_c)}\\right|$", "$\\left|\\dfrac{f(x_c)}{f'(x_c)}\\right|$", "$\\left|\\dfrac{x_cf(x_c)}{f'(x_c)}\\right|$", "$\\left|\\dfrac{f(x_c)}{x_c}\\right|$"], 0, "(derived) Newton step: absolute error $\\approx|f(x_c)/f'(x_c)|$ " + LS(2) + "\nDivide by $|x_c|$ to make it relative.", s)
tf("ex-05", T, "Gauss elimination is insensitive to ill-conditioning.", False, "No direct method can fix an ill-conditioned system: about $\\log_{10}\\mathrm{cond}(A)$ digits are lost whatever the algorithm " + LS(3) + ".", s)
mcq("ex-06", T, "The interpolating polynomial through 8 distinct data points has degree at most:", ["7", "8", "9", "4"], 0, "$n$ points → degree $\\le n-1$ (8 unknown coefficients) " + LS(4) + ".", s)
tf("ex-07", T, "The more data points used for interpolation, the more accurate the result.", False, "With equally spaced points, high degrees oscillate near the ends (Runge phenomenon) " + LS(4) + ".", s)
mcq("ex-08", T, "$\\mathrm{cond}(A)$ for a $1\\times1$ matrix $A=[a]$, $a\\ne0$ (any norm) is:", ["1", "$|a|$", "$1/|a|$", "$a^2$"], 0, "$\\|A\\|\\,\\|A^{-1}\\|=|a|\\cdot\\dfrac1{|a|}=1$ " + LS(3) + ".", s)
tf("ex-09", T, "If $|f(x_1)|<|f(x_2)|$ for two approximations of the same root, then $x_1$ is necessarily the better one.", False, "A smaller backward error doesn't guarantee a smaller forward error. A flat or steep $f$ changes the relation " + LS(2) + ".", s)
tf("ex-10", T, "In interpolation, the number of unknown coefficients equals the number of data points.", True, "Each point gives one equation, so the system is square (e.g. a Vandermonde matrix) " + LS(4) + ".", s)
sa("ex-11", T, "Match each error type to its source: round-off, truncation, propagation.", "Round-off: storing a finite number of digits. Truncation: using an approximate expression in place of an exact one. Propagation: errors in the input carried into the output.", "Error taxonomy " + LS(1), s, ["round-off: finite digits", "truncation: approximate formula", "propagation: input errors"])
mcq("ex-12", T, "With the stopping criterion $\\varepsilon_s=0.5\\times10^{2-n}\\,\\%$, meeting it guarantees:", ["At least $n$ significant digits", "$n$ decimal places", "An absolute error below $10^{-n}$", "$n$ iterations"], 0, "Scarborough criterion " + LS(1) + "\nIf $|\\varepsilon_a|<\\varepsilon_s$, the result is correct to at least $n$ significant figures.", s)
mcq("ex-13", T, "The approximate relative error of iterate $x_{i+1}$ is:", ["$\\varepsilon_a=\\left|\\dfrac{x_{i+1}-x_i}{x_{i+1}}\\right|\\times100\\%$", "$\\left|\\dfrac{x_{i+1}-x_i}{x_i}\\right|$", "$|x_{i+1}-x_i|$", "$\\left|\\dfrac{x_{true}-x_{i+1}}{x_{true}}\\right|$"], 0, "Approximate relative error " + LS(1) + "\nDivide by the NEWEST estimate. The last option is the true relative error, which needs the exact value.", s)

T = "Errors & fundamentals"; s = L(1, "Introduction and Fundamentals")
tf("er-02", T, "Making the step size $h$ smaller always reduces the total numerical error.", False, "Truncation error falls as $h$ shrinks, but round-off grows (cancellation) " + LS(1) + ".\nThe total error has a minimum at an optimal $h$.", s)
mcq("er-03", T, "A truncation error of $O(h^2)$ means that halving $h$ reduces the error by about:", ["4", "2", "8", "16"], 0, "$(1/2)^2=1/4$. For $O(h^4)$ it's 16.", s)
mcq("er-04", T, "Truncating a Taylor series after the $h^n$ term leaves a remainder of order:", ["$O(h^{n+1})$", "$O(h^n)$", "$O(h^{n-1})$", "$O(1)$"], 0, "Remainder $R_n=\\dfrac{f^{(n+1)}(\\xi)}{(n+1)!}h^{n+1}$ " + LS(1) + "\nUse it to bound the truncation error.", s)
tf("er-05", T, "The true error needs the exact answer, so algorithms stop on an estimated error, such as the change between iterates.", True, "Example: stop when $|\\varepsilon_a|<\\varepsilon_s$ " + LS(1) + ".", s)
mcq("er-06", T, "Subtracting two nearly equal floating-point numbers mainly causes:", ["Loss of significant digits (cancellation)", "Overflow", "Truncation error", "No error"], 0, "This is why forward differences go bad when $h$ is tiny " + LS(6) + ".", L(6, "Numerical Differentiation"))

T = "Nonlinear equations"; s = L(2, "Non-linear Equations")
mcq("nl-01", T, "Which two root-finding methods are bracketing methods?", ["Bisection and false position", "Newton and fixed-point", "Newton and secant", "Fixed-point and bisection"], 0, "Bracketing methods need $f(a)f(b)<0$ and always converge. Open methods may diverge " + LS(2) + ".", s)
tf("nl-02", T, "Bisection is guaranteed to converge for continuous $f$ with $f(a)f(b)<0$.", True, "The IVT puts a root in $[a,b]$, and the bracket halves each step " + LS(2) + ".", s)
mcq("nl-03", T, "After $n$ bisection steps from $[a,b]$, the error bound of the midpoint is:", ["$\\dfrac{b-a}{2^{n+1}}$", "$\\dfrac{b-a}{n}$", "$(b-a)^n$", "$\\dfrac{b-a}{2n}$"], 0, "Error bound " + LS(2) + "\nSolve $\\frac{b-a}{2^{n+1}}<\\text{TOL}$ for $n$ to get the number of steps without iterating.", s)
mcq("nl-04", T, "Bisection converges:", ["Linearly, with ratio 1/2", "Quadratically", "Superlinearly", "Cubically"], 0, "Each step gains about one binary digit (about 0.3 decimal digits) " + LS(2) + ".", s)
mcq("nl-05", T, "Fixed-point iteration $x_{i+1}=g(x_i)$ converges locally to $r$ if:", ["$|g'(r)|<1$", "$|g'(r)|>1$", "$g(r)=0$", "$g'(r)=1$"], 0, "Convergence is linear, with $e_{n}\\approx|g'(r)|^ne_0$ " + LS(2) + ".\n$|g'(r)|>1$ means the errors grow.", s)
tf("nl-06", T, "$f(x)=0$ can be rewritten as $x=g(x)$ in several ways, and some converge while others diverge.", True, "Pick a $g$ with $|g'(r)|<1$, and the smaller the better " + LS(2) + ".", s)
mcq("nl-07", T, "The Newton–Raphson update is:", ["$x_{i+1}=x_i-\\dfrac{f(x_i)}{f'(x_i)}$", "$x_{i+1}=x_i-f'(x_i)f(x_i)$", "$x_{i+1}=\\dfrac{x_i+f(x_i)}{2}$", "$x_{i+1}=g(x_i)$ with $g=f$"], 0, "Newton " + LS(2) + "\nFollow the tangent line down to the $x$-axis. The minus sign takes you downhill toward the root.", s)
mcq("nl-08", T, "Newton at a root of multiplicity $m>1$ converges:", ["Only linearly, with ratio $(m-1)/m$", "Quadratically", "Cubically", "Not at all"], 0, "Quadratic convergence needs $f'(r)\\ne0$ " + LS(2) + ".\nModified Newton $x_{i+1}=x_i-m\\,f/f'$ restores it.", s)
tf("nl-09", T, "Newton's method always converges, whatever the initial guess.", False, "It's an open method: a bad start, a near-zero $f'$ or cycling can make it fail " + LS(2) + ".", s)
mcq("nl-10", T, "The backward error of an approximate root $x_a$ is:", ["$|f(x_a)|$", "$|r-x_a|$", "$|x_a|$", "$|f'(x_a)|$"], 0, "Forward error $=|r-x_a|$ " + LS(2) + ".\nA small backward error doesn't guarantee a small forward error.", s)
sa("nl-11", T, "Why are multiple roots ill-conditioned?", "Near a root of multiplicity $m$, $f$ is very flat ($f'(r)=0$). A tiny backward error $|f(x_a)|$ allows a large forward error, roughly $(m!\\,|f(x_a)|/|f^{(m)}|)^{1/m}$.", "The error magnification factor is large (the Wilkinson polynomial idea) " + LS(2) + ".", s, ["flat f", "small backward, large forward", "magnification"])
mcq("nl-12", T, "The error magnification factor is:", ["Relative forward error ÷ relative backward error", "Forward × backward", "Backward ÷ forward", "Iterations ÷ tolerance"], 0, "Definition " + LS(2) + "\nA large factor means the problem is ill-conditioned.", s)
mcq("nl-13", T, "A method converges with order $q$ if:", ["$e_{i+1}\\approx C\\,e_i^q$", "$e_{i+1}\\approx Cq\\,e_i$", "$e_{i+1}=e_i-q$", "$e_i\\approx q^i$"], 0, "Order " + LS(2) + "\n$q=1$: linear (needs $C<1$). $q=2$: quadratic (correct digits roughly double each step).", s)

T = "Linear systems"; s = L(3, "Linear Equations")
tf("ls-01", T, "Gauss elimination and LU have no truncation error, only round-off.", True, "They're direct methods: exact in exact arithmetic " + LS(3) + ".", s)
sa("ls-02", T, "What are the two stages of Gauss elimination?", "Forward elimination (reduce to upper-triangular form), then back substitution.", "Cost " + LS(3) + ":\nforward elimination ≈ $\\tfrac23n^3$ operations\nback substitution ≈ $n^2$", s, ["forward elimination", "back substitution"])
mcq("ls-03", T, "Partial pivoting means:", ["Swapping rows so the pivot is the largest-magnitude entry in its column (at or below the diagonal)", "Swapping columns at random", "Dividing rows by their largest entry", "Skipping zero pivots"], 0, "It avoids dividing by zero or by tiny pivots, which would blow up round-off " + LS(3) + ".", s)
tf("ls-04", T, "Naive Gauss elimination can fail even when the system has a unique solution.", True, "Example: $a_{11}=0$. Pivoting fixes it " + LS(3) + ".", s)
mcq("ls-05", T, "The main advantage of LU over plain Gauss elimination is:", ["Once $A=LU$ is computed, each new $b$ costs only two triangular solves", "No round-off", "Works for singular $A$", "Never needs pivoting"], 0, "Solve $Ld=b$ (forward), then $Ux=d$ (back), each $O(n^2)$ " + LS(3) + ".", s)
mcq("ls-06", T, "With pivoting, the factorization is:", ["$PA=LU$", "$A=LUP$", "$A=PLU^T$", "$A=L+U$"], 0, "$P$ is a permutation matrix. Then $LUx=Pb$ " + LS(3) + ".", s)
mcq("ls-07", T, "The infinity norm $\\|x\\|_\\infty$ is:", ["$\\max_i|x_i|$", "$\\sum|x_i|$", "$\\sqrt{\\sum x_i^2}$", "$\\min|x_i|$"], 0, "Norms " + LS(3) + "\n$\\|A\\|_\\infty$ is the largest absolute row sum.", s)
mcq("ls-08", T, "$\\mathrm{cond}(A)=\\|A\\|\\|A^{-1}\\|$ is:", ["The largest possible error magnification factor for $Ax=b$", "The number of iterations", "$\\det A$", "The rank"], 0, "Condition number " + LS(3) + "\nIt's always $\\ge1$. Large means ill-conditioned.", s)
mcq("ls-09", T, "If $\\mathrm{cond}(A)\\approx10^k$, about how many significant digits are lost?", ["$k$", "$2k$", "$k/2$", "$10^k$"], 0, "Rule of thumb " + LS(3) + "\nIn double precision (about 16 digits) with $\\mathrm{cond}=10^{10}$, only about 6 digits can be trusted.", s)
tf("ls-10", T, "A small residual $\\|b-Ax_a\\|$ guarantees $x_a$ is close to the true solution.", False, "The residual is the backward error. With large $\\mathrm{cond}(A)$ the forward error can still be large " + LS(3) + ".", s)
tf("ls-11", T, "Two nearly identical equations (nearly parallel lines) make an ill-conditioned system.", True, "Tiny changes in the data move the intersection point a lot " + LS(3) + ".", s)

T = "Regression & interpolation"; s = L(4, "Regression and Interpolation")
sa("ri-01", T, "What's the difference between regression and interpolation?", "Regression finds the least-squares best fit to noisy data and needn't pass through the points. Interpolation passes exactly through every point.", "Use regression for measured data and interpolation for exact tabulated values " + LS(4) + ".", s, ["regression: best fit", "interpolation: through points"])
mcq("ri-02", T, "Linear least squares minimizes:", ["$SE=\\sum r_i^2$", "The largest residual", "$\\sum r_i$", "The number of points"], 0, "Setting the partial derivatives to zero gives the normal equations $A^TA\\hat a=A^Ty$ " + LS(4) + ".", s)
mcq("ri-03", T, "The RMSE of a fit is:", ["$\\sqrt{SE/m}$", "$SE/m$", "$\\sqrt{SE}$", "$SE\\cdot m$"], 0, "MSE $=SE/m$ and RMSE $=\\sqrt{MSE}$, with $m$ = number of points " + LS(4) + ".", s)
tf("ri-04", T, "'Linear' regression means linear in the parameters, so $y=a_1+a_2x+a_3x^2$ counts.", True, "The basis functions can be nonlinear in $x$ " + LS(4) + ".", s)
mcq("ri-05", T, "To fit $y=c\\,e^{kx}$ with linear least squares, you:", ["Take logs: $\\ln y=\\ln c+kx$, then fit a line", "Fit $y$ directly", "Take $\\sqrt y$", "Interpolate"], 0, "Linearization " + LS(4) + "\nPower law: $\\ln y=\\ln c+k\\ln x$ (the Moore's-law example).", s)
tf("ri-06", T, "The least-squares residual vector is orthogonal to the columns of $A$.", True, "$A^T(y-A\\hat a)=0$ is exactly the normal equations " + LS(4) + ".", s)
mcq("ri-07", T, "Through $n$ distinct points there's a unique interpolating polynomial of degree at most:", ["$n-1$", "$n$", "$n+1$", "$2n$"], 0, "Vandermonde, Newton and Lagrange are the same polynomial written differently " + LS(4) + ".", s)
tf("ri-08", T, "The Vandermonde matrix is often badly conditioned, which is one reason to prefer the Newton or Lagrange forms.", True, "Its columns $1, x, x^2, \\dots$ become nearly parallel " + LS(4) + ".", s)
mcq("ri-09", T, "A practical advantage of Newton's divided differences is:", ["A new point adds only one new term; earlier coefficients are reused", "No arithmetic needed", "Lower degree", "No round-off"], 0, "The coefficients are the top diagonal of the divided-difference table " + LS(4) + ".", s)
sa("ri-10", T, "State the interpolation error theorem and how to reduce the error.", "$f(x)-P(x)=\\frac{(x-x_1)\\cdots(x-x_n)}{n!}f^{(n)}(c)$. Place the nodes well, e.g. Chebyshev points clustered toward the ends rather than equally spaced.", "Error theorem " + LS(4) + "\nEqually spaced, high-degree interpolation oscillates near the ends (Runge).", s, ["product (x−xi)", "f^(n)/n!", "Chebyshev", "Runge"])
tf("ri-11", T, "Raising the degree of an equally spaced interpolant always improves accuracy.", False, "Runge phenomenon " + LS(4) + ".", s)
mcq("ri-12", T, "Cubic splines are continuous at interior knots in:", ["Function, first and second derivatives", "Only the function", "Function and first derivative only", "All derivatives"], 0, "End conditions (natural, clamped) supply the last two equations " + LS(4) + ".", s)

T = "Numerical differentiation"; s = L(6, "Numerical Differentiation")
mcq("nd-01", T, "The forward difference $\\dfrac{f(x+h)-f(x)}{h}$ has truncation error:", ["$O(h)$", "$O(h^2)$", "$O(h^3)$", "$O(1)$"], 0, "(derived) Taylor: $f(x+h)=f+hf'+\\frac{h^2}2f''+\\dots$\nRearrange: error $=\\frac h2f''$, i.e. $O(h)$.\nCentral difference $\\frac{f(x+h)-f(x-h)}{2h}$ is $O(h^2)$ " + LS(6) + ".", s)
mcq("nd-02", T, "The three-point central difference for $f''(x)$ is:", ["$\\dfrac{f(x+h)-2f(x)+f(x-h)}{h^2}$, $O(h^2)$", "$\\dfrac{f(x+h)-f(x-h)}{2h}$", "$\\dfrac{f(x+h)-2f(x)}{h^2}$", "$\\dfrac{f(x+2h)-f(x)}{2h}$"], 0, "(derived) Add the Taylor series of $f(x+h)$ and $f(x-h)$: the odd terms cancel " + LS(6) + ".", s)
sa("nd-03", T, "Why is there an optimal step size $h$ for numerical differentiation?", "Total error = truncation (shrinks with $h$, e.g. $\\propto h^2$) + round-off (grows like $\\epsilon_{mach}/h$ from cancellation). The sum has a minimum.", "For the central difference, $h_{opt}\\sim\\epsilon_{mach}^{1/3}\\approx10^{-5}$ in double precision " + LS(6) + ".", s, ["truncation down", "round-off up", "minimum"])
tf("nd-04", T, "Higher-order difference formulas allow a larger optimal $h$ and a smaller minimum error.", True, "Truncation error falls faster, so round-off takes over later " + LS(6) + ".", s)

T = "Numerical integration"; s = L(7, "Numerical Integration")
mcq("ni-01", T, "Newton–Cotes formulas come from:", ["Integrating an interpolating polynomial through equally spaced points", "Optimal non-uniform nodes", "A least-squares line", "Taylor series only"], 0, "Closed formulas (trapezoid, Simpson) include the endpoints; open formulas (midpoint) don't " + LS(7) + ".", s)
mcq("ni-02", T, "The composite trapezoid rule has global error:", ["$O(h^2)$", "$O(h)$", "$O(h^3)$", "$O(h^4)$"], 0, "One panel: $-\\frac{h^3}{12}f''(c)$. Summing $n\\propto1/h$ panels loses one order " + LS(7) + ".", s)
mcq("ni-03", T, "The composite Simpson's 1/3 rule has global error:", ["$O(h^4)$", "$O(h^2)$", "$O(h^3)$", "$O(h^5)$"], 0, "Halving $h$ cuts the error by about 16. It needs an even number of subintervals " + LS(7) + ".", s)
mcq("ni-04", T, "The degree of precision of Simpson's rule is:", ["3", "2", "1", "4"], 0, "It's exact for cubics, one degree more than expected from the parabola fit, because the errors cancel by symmetry " + LS(7) + ".", s)
tf("ni-05", T, "Composite Simpson's rule needs an even number of subintervals.", True, "Each application covers 2 subintervals (3 points) " + LS(7) + ".", s)
mcq("ni-06", T, "Halving $h$ in the composite trapezoid rule cuts the error by about:", ["4", "2", "8", "16"], 0, "A ratio near 4 confirms $O(h^2)$ " + LS(7) + ".", s)
sa("ni-07", T, "What is Richardson extrapolation used for in integration?", "Combining estimates with steps $h$ and $h/2$ to estimate and cancel the leading error term. For an $O(h^n)$ method: error ≈ $\\frac{I_{h/2}-I_h}{2^n-1}$; improved value $=I_{h/2}+\\frac{I_{h/2}-I_h}{2^n-1}$.", "Richardson " + LS(7) + "\nApplying it repeatedly to the trapezoid rule gives Romberg integration.", s, ["two step sizes", "estimate error", "cancel leading term"])
mcq("ni-08", T, "Romberg integration is:", ["Repeated Richardson extrapolation of trapezoid estimates", "Random-node Gauss quadrature", "Simpson's 3/8", "Monte Carlo"], 0, "Each column raises the order by 2 " + LS(7) + ".", s)
mcq("ni-09", T, "$n$-point Gauss quadrature is exact up to degree:", ["$2n-1$", "$n-1$", "$n$", "$2n$"], 0, "Both the nodes (roots of Legendre polynomials) and the weights are chosen optimally " + LS(7) + ".", s)
tf("ni-10", T, "Gauss quadrature needs $f$ at non-uniform points, so it suits a known function better than tabulated equally spaced data.", True, "For tabulated data, use composite Newton–Cotes " + LS(7) + ".", s)

T = "Initial value problems"; s = L(8, "Initial Value Problems")
mcq("iv-01", T, "Euler's method update for $y'=f(t,y)$ is:", ["$w_{i+1}=w_i+h\\,f(t_i,w_i)$", "$w_{i+1}=w_i+\\frac h2[f(t_i,w_i)+f(t_{i+1},w_{i+1})]$", "$w_{i+1}=w_i+h\\,f(t_{i+1},w_{i+1})$", "$w_{i+1}=w_i-h\\,f'(t_i)$"], 0, "Explicit, first order: follow the slope at the start of the step " + LS(8) + ".", s)
mcq("iv-02", T, "Euler's local and global truncation errors are:", ["$O(h^2)$ local, $O(h)$ global", "$O(h)$ local, $O(h^2)$ global", "$O(h^2)$ both", "$O(h^3)$ local, $O(h^2)$ global"], 0, "Errors build up over about $1/h$ steps, so the global order is one less " + LS(8) + ".", s)
mcq("iv-03", T, "Classical RK4 has global error:", ["$O(h^4)$", "$O(h^2)$", "$O(h^5)$", "$O(h)$"], 0, "Four slope evaluations per step; local error $O(h^5)$ " + LS(8) + ".", s)
mcq("iv-04", T, "The explicit trapezoid (Heun) and midpoint methods are:", ["Second-order Runge–Kutta methods", "First order", "Fourth order", "Implicit multistep"], 0, "Two slope evaluations per step; global error $O(h^2)$ " + LS(8) + ".", s)
sa("iv-05", T, "What's the idea behind Runge–Kutta compared with Euler?", "Evaluate the slope at several points inside the step and take a weighted average. This gives higher accuracy without derivatives of $f$.", "Taylor methods also reach higher order, but they need derivatives of $f$ " + LS(8) + ".", s, ["several slopes", "weighted average", "no derivatives of f"])
sa("iv-06", T, "What does the Lipschitz condition guarantee for an IVP?", "If $|f(t,y_1)-f(t,y_2)|\\le L|y_1-y_2|$, the IVP has a unique solution, and nearby solutions separate by at most a factor $e^{L(t-t_0)}$, so errors can grow over time.", "This explains why the global error can grow exponentially in $t$ " + LS(8) + ".", s, ["existence & uniqueness", "e^{L(t−t0)}", "sensitivity"])
tf("iv-07", T, "For a stiff or fast-decaying problem, Euler with too large a step can give growing oscillations even though the true solution decays.", True, "For $y'=-\\lambda y$, Euler is stable only if $h<2/\\lambda$ " + LS(8) + ".", s)
mcq("iv-08", T, "A higher-order ODE like $y''=f(t,y,y')$ is solved with IVP solvers by:", ["Rewriting it as a first-order system: $y_1=y$, $y_2=y'$", "Applying Euler to $y''$", "Integrating twice analytically", "It can't be"], 0, "The pendulum and orbit examples " + LS(8) + ".", s)
tf("iv-09", T, "For very small step sizes, round-off can make IVP results worse.", True, "The total error vs $h$ again has a minimum " + LS(8) + ".", s)
mcq("iv-10", T, "Using Richardson with steps $h$ and $h/2$ for an order-$n$ method, the estimated error of $w_{h/2}$ is:", ["$\\dfrac{w_{h/2}-w_h}{2^n-1}$", "$w_{h/2}-w_h$", "$\\dfrac{w_h}{2^n}$", "$2^n(w_{h/2}-w_h)$"], 0, "This is the basis for error control and step-size selection " + LS(8) + ".", s)
